"""Read-only gate judgment for the Merge summary writer, from the verified default checkout."""

import argparse
import hashlib
import json
import re
import subprocess
import sys
from datetime import datetime
from urllib.parse import quote

sys.dont_write_bytecode = True
import gate
from branch_rules import ACTIONS_APP, read

REPOSITORY = "@@repository@@"
SHA = re.compile(r"[0-9a-f]{40}")


def snapshot(number, reviewed):
    path = "repos/" + REPOSITORY
    repo = read(path)
    branch, repository, owner = repo["default_branch"], repo["full_name"], repo["owner"]["login"]
    if (not gate.is_text(branch) or repository.lower() != REPOSITORY.lower()
            or type(repo["id"]) is not int or repository.split("/")[0].lower() != owner.lower()):
        raise ValueError("repository identity or default branch unreadable")
    tip = read(path + "/git/ref/heads/" + quote(branch, safe="/"))
    base = tip["object"]["sha"]
    if tip["ref"] != "refs/heads/" + branch or tip["object"]["type"] != "commit" or not SHA.fullmatch(base):
        raise ValueError("default branch tip unreadable")
    pull = read(path + "/pulls/" + str(number))
    target = pull["base"]
    head = pull["head"]["sha"]
    if (type(pull["number"]) is not int or pull["number"] != number or pull["state"] != "open"
            or target["ref"] != branch or target["repo"]["id"] != repo["id"]
            or target["repo"]["full_name"] != repository or head != reviewed or not SHA.fullmatch(head)):
        raise ValueError("the named open PR, default target or reviewed head no longer matches")
    author, body = pull["user"]["login"], pull["body"]
    if not gate.is_text(author) or (body is not None and not isinstance(body, str)):
        raise ValueError("PR author or body unreadable")
    metadata = json.dumps([owner, author, body], ensure_ascii=True).encode("ascii")
    facts = dict(repository=repository, repository_id=repo["id"], pr=number, target=branch,
                 base=base, head=head, metadata=hashlib.sha256(metadata).hexdigest())
    return facts, owner, author, body


# Pin all pages to the reviewed object. GitHub supplies requiredness for this PR.
CHECKS_QUERY = """query($owner:String!, $repo:String!, $head:GitObjectID!, $pr:Int!, $endCursor:String) {
  repository(owner:$owner, name:$repo) {
    object(oid:$head) { ... on Commit {
      oid
      statusCheckRollup { contexts(first:100, after:$endCursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          ... on CheckRun {
            name status conclusion completedAt isRequired(pullRequestNumber:$pr)
            checkSuite { app { databaseId } workflowRun { event workflow { id } } }
          }
          ... on StatusContext { name:context state createdAt isRequired(pullRequestNumber:$pr) }
        }
      } }
    } }
  }
}"""


def check_result(row):
    """A check's producer, ordering within that producer, and green state."""
    name = row["name"]
    if not gate.is_text(name):
        raise ValueError("required check name unreadable")
    if "state" in row:
        created = datetime.fromisoformat(row["createdAt"].replace("Z", "+00:00"))
        return (name, "status"), created, row["state"] == "SUCCESS" and name != gate.CHECK
    suite = row["checkSuite"]
    app = (suite["app"] or {}).get("databaseId")
    run = suite["workflowRun"] or {}
    producer = (name, "run", app, (run.get("workflow") or {}).get("id"), run.get("event"))
    if row["status"] != "COMPLETED" or not row["completedAt"]:
        raise ValueError("required check has not finished: " + name)
    completed = datetime.fromisoformat(row["completedAt"].replace("Z", "+00:00"))
    passed = row["conclusion"] == "SUCCESS" and (name != gate.CHECK or app == ACTIONS_APP)
    return producer, completed, passed


def check_required(facts):
    owner, repo = facts["repository"].split("/")
    args = ["gh", "api", "graphql", "--paginate", "--slurp", "-f", "owner=" + owner, "-f", "repo=" + repo,
            "-f", "head=" + facts["head"], "-F", "pr=" + str(facts["pr"]), "-f", "query=" + CHECKS_QUERY]
    pages = json.loads(subprocess.check_output(args))
    if not isinstance(pages, list) or not pages:
        raise ValueError("required checks unreadable")
    latest = {}
    for index, page in enumerate(pages):
        commit = page["data"]["repository"]["object"]
        if page.get("errors") or commit["oid"] != facts["head"]:
            raise ValueError("required checks do not identify the reviewed commit")
        contexts = commit["statusCheckRollup"]["contexts"]
        if contexts["pageInfo"]["hasNextPage"] is not (index + 1 < len(pages)) or not isinstance(contexts["nodes"], list):
            raise ValueError("required check pages incomplete")
        for row in contexts["nodes"]:
            if type(row["isRequired"]) is not bool:
                raise ValueError("required check attribution unreadable")
            if row["isRequired"]:
                producer, order, passed = check_result(row)
                if producer not in latest or order > latest[producer][0]:
                    latest[producer] = order, passed
                elif order == latest[producer][0] and not passed:
                    latest[producer] = order, False
    record = subprocess.check_output(["git", "show", facts["base"] + ":" + gate.RECORD])
    required = set(gate.parse_record(record)["confirmed"]["required_checks"]) | {gate.CHECK}
    for producer, (_, passed) in latest.items():
        if not passed:
            raise ValueError("required check unsuccessful: " + producer[0])
        required.discard(producer[0])
    if required:
        raise ValueError("missing required check: " + ", ".join(sorted(required)))


def run(args):
    facts, owner, author, body = snapshot(args.number, args.reviewed)
    tip = subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip()
    dirty = subprocess.check_output(["git", "status", "--porcelain", "--untracked-files=all", "--ignored"])
    if tip != facts["base"] or dirty:
        raise ValueError("use a clean checkout of the current remote default tip")
    head = facts["head"]
    if not gate._is_commit(".", head) and not gate._fetch(".", head):
        raise ValueError("reviewed head objects unavailable")
    lookup = gate._merged_lookup(facts["repository"], facts["target"])
    unreadable = False

    def merged(sha):
        nonlocal unreadable
        found = lookup(sha)
        if found is None:
            unreadable = True
        return found

    verdict = gate.verdict(".", author, owner, body, tip, head, merged)
    if unreadable:
        raise ValueError("pure-revert association unreadable; retry")
    receipt = json.dumps(dict(facts, pure_revert=verdict["pure_revert"], outcome="pass" if verdict["passed"] else "fail"), sort_keys=True)
    if not verdict["passed"]:
        print(receipt)
        raise ValueError("gate failed: " + " ".join(verdict["failures"]))

    if args.mode == "confirm":
        if sys.stdin.read().strip() != receipt:
            raise ValueError("recorded passing receipt missing or changed; evaluate again")
        check_required(facts)
        current, _, _, _ = snapshot(args.number, args.reviewed)
        if current != facts:
            raise ValueError("inputs changed during confirmation; evaluate again")
    print(receipt)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("judge", "confirm"))
    parser.add_argument("number", type=int)
    parser.add_argument("reviewed", help="full reviewed head SHA from the Merge summary")
    try:
        run(parser.parse_args())
    except (ValueError, KeyError, TypeError, AttributeError, OSError, gate.GitError, subprocess.CalledProcessError) as error:
        sys.exit("Hold merge handoff: %s" % error)
